<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Split Online','description'=>'Extract selected pages from a PDF and download a new PDF in your browser.','url'=>'https://smarttoolz.in/tools/pdf-split/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PDF SPLIT</span><h1>Split PDF Pages</h1><p>Choose a PDF and enter the page numbers you want to extract.</p></section><section class="tool-workspace"><div class="tool-panel"><label>PDF file<input id="f" type="file" accept="application/pdf"></label><label>Pages<input id="p" placeholder="Example: 1,3,5-7"></label><button id="go" class="tool-btn">Extract Pages</button><p id="out"></p></div></section></main><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script>(()=>{const $=id=>document.getElementById(id);function nums(s,max){let a=new Set();for(let x of s.split(',')){x=x.trim();if(/^\d+$/.test(x))a.add(+x-1);else if(/^(\d+)-(\d+)$/.test(x)){let [q,r]=x.split('-').map(Number);for(let i=q;i<=r;i++)a.add(i-1)}}return [...a].filter(i=>i>=0&&i<max).sort((a,b)=>a-b)}$('go').onclick=async()=>{let f=$('f').files[0];if(!f){$('out').textContent='Choose a PDF.';return}try{let src=await PDFLib.PDFDocument.load(await f.arrayBuffer()),ix=nums($('p').value,src.getPageCount());if(!ix.length){$('out').textContent='Enter valid page numbers.';return}let out=await PDFLib.PDFDocument.create();(await out.copyPages(src,ix)).forEach(p=>out.addPage(p));let blob=new Blob([await out.save()],{type:'application/pdf'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='split.pdf';a.click();$('out').textContent=`Extracted ${ix.length} page(s).`}catch(e){$('out').textContent='Could not read this PDF.'}}})();</script><?php smarttoolz_tool_page_end(); ?>